// Indicateurs pour Power BI, calculés à partir des deux tables Airtable.
// Seules des métadonnées sortent : ni texte de REX, ni hypothèse, ni sys_id.
const lignes = (nom) => $(nom).all().map((i) => i.json).filter((r) => r && r.id);
const candidats = lignes('Lire les candidats');
const rex = lignes('Lire les REX');

const compter = (liste, ...statuts) => liste.filter((r) => statuts.includes(r.Statut)).length;
const moyenne = (valeurs) => valeurs.length
  ? Math.round((valeurs.reduce((a, b) => a + b, 0) / valeurs.length) * 10) / 10
  : null;
const nombre = (v) => (typeof v === 'number' && Number.isFinite(v) ? v : null);

// Un candidat « Créé » a d'abord été validé : il compte parmi les validés.
const valides = compter(candidats, 'Validé', 'Créé');
const rejetes = compter(candidats, 'Rejeté');

// Délai de relecture : de la création du brouillon à sa dernière modification,
// qui pour un REX publié est le passage à « Publié » par WF2b.
const delais = rex
  .filter((r) => r.Statut === 'Publié' && r.createdTime && r['Modifié le'])
  .map((r) => (new Date(r['Modifié le']) - new Date(r.createdTime)) / 3600000)
  .filter((h) => h >= 0);

const durees = rex.map((r) => nombre(r['Durée (min)'])).filter((d) => d !== null);

const synthese = {
  problemes_proposes: candidats.length,
  problemes_a_trier: compter(candidats, 'À trier'),
  problemes_valides: valides,
  problemes_rejetes: rejetes,
  problemes_crees: compter(candidats, 'Créé'),
  taux_validation_pct: valides + rejetes ? Math.round((valides / (valides + rejetes)) * 100) : null,
  incidents_regroupes: candidats.reduce((s, r) => s + (nombre(r['Nb incidents']) || 0), 0),
  rex_rediges: rex.length,
  rex_a_relire: compter(rex, 'À relire'),
  rex_publies: compter(rex, 'Publié'),
  delai_relecture_moyen_h: moyenne(delais),
  mttr_p1_min: moyenne(durees),
};

// Tables de détail, une ligne par enregistrement, pour les visuels Power BI.
const problemes = candidats
  .map((r) => ({
    signature: r.Signature || null,
    ci: r.CI || null,
    nb_incidents: nombre(r['Nb incidents']) || 0,
    statut: r.Statut || null,
    probleme: r['Problème'] || null,
    propose_le: r.createdTime || null,
  }))
  .sort((a, b) => b.nb_incidents - a.nb_incidents);

const rexDetail = rex.map((r) => ({
  incident: r.Incident || null,
  titre: r.Titre || null,
  duree_min: nombre(r['Durée (min)']),
  statut: r.Statut || null,
  redige_le: r.createdTime || null,
}));

return [{ json: { genere_le: new Date().toISOString(), synthese, problemes, rex: rexDetail } }];
